def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    # If opponent has been defecting heavily while we cooperate, switch to always defect.
    if n >= 10:
        myD = 0
        opD = 0
        for i in range(n):
            if my[i] == 'D':
                myD += 1
            if op[i] == 'D':
                opD += 1
            if i >= 9:
                if myD * 2 < (i + 1) and opD * 2 > (i + 1):
                    return 'D'

    opD_total = op.count('D')
    opC = n - opD_total
    myD_total = my.count('D')

    if n >= 2:
        if my[-1] == 'D' and op[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
            return 'C'

    if n < 4:
        if opD_total == 0:
            return 'C'
        if opD_total == n:
            return 'D'
        return 'C'

    opp_last = op[-1]
    if opp_last == 'D':
        if opD_total >= 3 and op[-2] == 'D' and op[-3] == 'D':
            return 'D'
        return 'D'

    if opD_total >= 4 and n >= 8:
        if myD_total > opD_total + 2:
            return 'C'

    if opC >= 3 and op[-1] == 'C' and op[-2] == 'C' and op[-3] == 'C':
        return 'C'

    if opD_total == 1 and n >= 6:
        return 'C'

    return 'C'
